WITH plus AS (
  SELECT molecule_id FROM molecule WHERE label = '+'
), f_mols AS (
  SELECT DISTINCT molecule_id FROM atom WHERE UPPER(element) = 'F' AND molecule_id IN (SELECT molecule_id FROM plus)
)
SELECT CASE WHEN (SELECT COUNT(*) FROM plus)=0 THEN 0.0
            ELSE (((SELECT COUNT(*) FROM plus) - (SELECT COUNT(*) FROM f_mols)) * 100.0) / (SELECT COUNT(*) FROM plus)
       END AS percentage_no_f;
